local CLIENT_BITS = { live = 1, forever = 2 }
local OPEN_LIBRARIES = { "bit" }

local function Present(flag, bit)
    return flag == 3 or flag == bit
end

local function Fields(source, bit)
    local fields = {}
    for name, flag in pairs(source) do
        if Present(flag, bit) then
            fields[name] = {}
        end
    end
    return fields
end

return function(client)
    local bit = assert(CLIENT_BITS[client], "unknown client")
    local readGlobals = {}
    for name, flag in pairs(GLOBALS) do
        if Present(flag, bit) then
            readGlobals[name] = { other_fields = true }
        end
    end
    for owner, fields in pairs(API) do
        readGlobals[owner] = { fields = Fields(fields, bit) }
    end
    local enums = {}
    for name, enum in pairs(ENUMS) do
        if Present(enum.flag, bit) then
            enums[name] = enum.values and { fields = Fields(enum.values, bit) } or { other_fields = true }
        end
    end
    readGlobals.Enum = { fields = enums }
    for _, name in ipairs(OPEN_LIBRARIES) do
        readGlobals[name] = { other_fields = true }
    end
    return { read_globals = readGlobals }
end
